INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-10-s0-1', 'exam-linear-algebra-set-10', 'exam-linear-algebra-set-10-sec-0', 0, '设向量组线性无关，则下列向量组', '设向量组 $\\alpha_{1}, \\alpha_{2}, \\alpha_{3}$ 线性无关，则下列向量组线性无关的是（）', '["$\\\\alpha_{1},\\\\alpha_{2},\\\\alpha_{1}+\\\\alpha_{2}$","$\\\\alpha_{1},\\\\alpha_{2},\\\\alpha_{1}-\\\\alpha_{2}$","$\\\\alpha_{1}-\\\\alpha_{2},\\\\alpha_{2}-\\\\alpha_{3},\\\\alpha_{3}-\\\\alpha_{1}$","$\\\\alpha_{1}+\\\\alpha_{2},\\\\alpha_{2}+\\\\alpha_{3},\\\\alpha_{3}+\\\\alpha_{1}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第10套', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
