INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-10-s2-1', 'exam-linear-algebra-set-10', 'exam-linear-algebra-set-10-sec-2', 3, '设矩阵,,求矩阵方程的解.', '设矩阵 $\\mathbf{A} = \\begin{pmatrix} 5 & 0 & 0 \\\\ 0 & 1 & 2 \\\\ 0 & 3 & 7 \\end{pmatrix}$ , $\\mathbf{B} = \\begin{pmatrix} 10 & 0 & 1 \\\\ 20 & 2 & 1 \\end{pmatrix}$ , 求矩阵方程 $X A = B$ 的解 $X$ .', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第10套', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-10-s2-2', 'exam-linear-algebra-set-10', 'exam-linear-algebra-set-10-sec-2', 3, '设为互不相等的常数，讨论向量组', '设 $t_{1}, t_{2}, t_{3}$ 为互不相等的常数，讨论向量组 $\\alpha_{1} = (1, t_{1}, t_{1}^{2}), \\alpha_{1} = (1, t_{2}, t_{2}^{2}), \\alpha_{1} = (1, t_{3}, t_{3}^{2})$ 的线性相关性.', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第10套', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-10-s2-3', 'exam-linear-algebra-set-10', 'exam-linear-algebra-set-10-sec-2', 3, '求线性方程组的通解', '求线性方程组 $\\left\\{\\begin{aligned} x_{1}+2x_{2}-x_{3}+2x_{4}=1 \\\\ 2x_{1}+4x_{2}+x_{3}+x_{4}=5 \\\\ -x_{1}-2x_{2}-2x_{3}+x_{4}=-4\\end{aligned}\\right.$ 的通解', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第10套', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-10-s2-4', 'exam-linear-algebra-set-10', 'exam-linear-algebra-set-10-sec-2', 3, '设矩阵（1）求矩阵的特征值和特', '设矩阵 $A = \\begin{pmatrix} -1 & 4 \\\\ -1 & 4 \\end{pmatrix}$ （1）求矩阵 $A$ 的特征值和特征向量；（2）问 $A$ 能否对角化？若能，求可逆矩阵 $P$ 及对角矩阵 $D$ ，使 $P^{-1}AP = D$ .', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第10套', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
